 CREATE OR REPLACE FUNCTION public.getpaymentdocument(v_contentid uuid)                                                                                                                                                                                                                                                                 
  RETURNS TABLE(payername text, memofirstname character varying, payeraddress character varying, payercity character varying, payerstatekey character varying, payerzipcode character varying, accountarea character varying, paymentnumber bigint, checknumber character varying, paymentdate character varying, paymentamount numeric)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                      
 AS $function$                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                      
 DECLARE                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                      
 BEGIN                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                      
 return query                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                      
 select concat(rfc.firstname,' ',rfc.lastname) as payername, rfc.customernumber as memofirstname,rfc.addressline1 as payeraddress,rfc.city as payercity,                                                                                                                                                                              
 rfc.state as payerstatekey,rfc.zip as payerzipcode, rfc.vakaccountnumber as accountarea, rfc.paymentno as paymentnumber, rfc.checkno as checknumber,                                                                                                                                                                                 
 rfc.asofdate as paymentdate, rfc.checkamt as paymentamount                                                                                                                                                                                                                                                                           
 from restitutionpaymentflatfilecontent rfc                                                                                                                                                                                                                                                                                           
 where restitutionpaymentflatfilecontentid=v_contentid;                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                      
 END;                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                      
 $function$                                                                                                                                                                                                                                                                                                                             

